CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY);
CREATE TABLE users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('operator','engineer','admin','manager')), password_hash TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires DOUBLE PRECISION NOT NULL);
CREATE TABLE equipment (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK(kind IN ('rack','ups')), location TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE sensors (id TEXT PRIMARY KEY, equipment_id TEXT NOT NULL REFERENCES equipment(id) ON DELETE RESTRICT, name TEXT NOT NULL, metric TEXT NOT NULL CHECK(metric IN ('temperature','humidity','charge','voltage')), unit TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE rules (sensor_id TEXT PRIMARY KEY REFERENCES sensors(id) ON DELETE RESTRICT, lower_bound DOUBLE PRECISION NOT NULL, upper_bound DOUBLE PRECISION NOT NULL, stale_seconds INTEGER NOT NULL CHECK(stale_seconds>=30), CHECK(lower_bound<upper_bound));
CREATE TABLE measurements (id TEXT PRIMARY KEY, sensor_id TEXT NOT NULL REFERENCES sensors(id) ON DELETE RESTRICT, packet_id TEXT NOT NULL, value DOUBLE PRECISION NOT NULL, measured_at DOUBLE PRECISION NOT NULL, received_at DOUBLE PRECISION NOT NULL, UNIQUE(sensor_id,packet_id), UNIQUE(sensor_id,measured_at));
CREATE INDEX measurement_time ON measurements(sensor_id,measured_at);
CREATE TABLE forecasts (id TEXT PRIMARY KEY, sensor_id TEXT NOT NULL REFERENCES sensors(id) ON DELETE RESTRICT, created_at DOUBLE PRECISION NOT NULL, horizon INTEGER NOT NULL, value DOUBLE PRECISION, slope DOUBLE PRECISION, threshold_at DOUBLE PRECISION, explanation TEXT NOT NULL, available INTEGER NOT NULL CHECK(available IN (0,1)));
CREATE INDEX forecast_time ON forecasts(sensor_id,created_at);
CREATE TABLE incidents (id TEXT PRIMARY KEY, equipment_id TEXT NOT NULL REFERENCES equipment(id) ON DELETE RESTRICT, sensor_id TEXT NOT NULL REFERENCES sensors(id) ON DELETE RESTRICT, forecast_id TEXT REFERENCES forecasts(id), problem TEXT NOT NULL CHECK(problem IN ('threshold','stale','risk')), priority TEXT NOT NULL CHECK(priority IN ('high','medium','low')), status TEXT NOT NULL CHECK(status IN ('new','acknowledged','working','review','closed')), assignee_id TEXT REFERENCES users(id), title TEXT NOT NULL, created_at DOUBLE PRECISION NOT NULL, updated_at DOUBLE PRECISION NOT NULL, normal_since DOUBLE PRECISION);
CREATE UNIQUE INDEX one_open_problem ON incidents(sensor_id,problem) WHERE status <> 'closed';
CREATE INDEX incident_status ON incidents(status,updated_at);
CREATE TABLE work_records (id TEXT PRIMARY KEY, incident_id TEXT NOT NULL REFERENCES incidents(id), author_id TEXT NOT NULL REFERENCES users(id), created_at DOUBLE PRECISION NOT NULL, result TEXT NOT NULL);
CREATE TABLE transitions (id TEXT PRIMARY KEY, incident_id TEXT NOT NULL REFERENCES incidents(id), author_id TEXT REFERENCES users(id), created_at DOUBLE PRECISION NOT NULL, from_status TEXT, to_status TEXT NOT NULL, comment TEXT NOT NULL);
CREATE INDEX transition_incident ON transitions(incident_id,created_at);
CREATE TABLE notifications (id TEXT PRIMARY KEY, incident_id TEXT NOT NULL REFERENCES incidents(id), created_at DOUBLE PRECISION NOT NULL, message TEXT NOT NULL);
CREATE TABLE notification_reads (notification_id TEXT NOT NULL REFERENCES notifications(id), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(notification_id,user_id));
CREATE TABLE settings (id INTEGER PRIMARY KEY CHECK(id=1), analysis_window INTEGER NOT NULL CHECK(analysis_window BETWEEN 300 AND 86400), horizon INTEGER NOT NULL CHECK(horizon BETWEEN 60 AND 7200), recovery_seconds INTEGER NOT NULL CHECK(recovery_seconds BETWEEN 30 AND 3600));
CREATE TABLE simulation (id INTEGER PRIMARY KEY CHECK(id=1), scenario TEXT NOT NULL, running INTEGER NOT NULL CHECK(running IN (0,1)), speed INTEGER NOT NULL CHECK(speed IN (1,5,15,30)), clock DOUBLE PRECISION NOT NULL, step INTEGER NOT NULL, lease_owner TEXT, lease_until DOUBLE PRECISION NOT NULL DEFAULT 0);
INSERT INTO schema_migrations(version) VALUES (1);
